INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2346794, 326566, 57229, '<td valign="top">Nice idea that self-ephased? Gets sort of lost between the abstract and the figurative. I guess that could be a good thing in some cases, but it doesn''t work for me here.</td>', 'Nice idea that self-ephased? Gets sort of lost between the abstract and the figurative. I guess that could be a good thing in some cases, but it doesn''t work for me here.', '2006-04-26 14:59:43.000000', NULL, 1),
(2346821, 326333, 47184, '<td valign="top">could be better</td>', 'could be better', '2006-04-26 15:06:01.000000', NULL, 1),
(2346893, 325980, 16402, '<td valign="top">Lighting is really harsh and I don''t see any significant amounts of yellow or red, which according to the challenge details would be the complimentary colors to purple or green respectively.</td>', 'Lighting is really harsh and I don''t see any significant amounts of yellow or red, which according to the challenge details would be the complimentary colors to purple or green respectively.', '2006-04-26 15:23:23.000000', NULL, 1),
(2346902, 325745, 16402, '<td valign="top">Really cool concept but not too blown away by the execution. Lots of dead space on left and something just weird (can''t really put my finger on it) about the purple coloring. DOF works pretty good.</td>', 'Really cool concept but not too blown away by the execution. Lots of dead space on left and something just weird (can''t really put my finger on it) about the purple coloring. DOF works pretty good.', '2006-04-26 15:26:01.000000', NULL, 1),
