(2352897, 323886, 52549, '<td valign="top">Only one word for this. Gorgeous.</td>', 'Only one word for this. Gorgeous.', '2006-04-28 09:45:23.000000', NULL, 1),
(2352900, 326353, 52549, '<td valign="top">Nice colours. Crisp and clear. Love the water drops.</td>', 'Nice colours. Crisp and clear. Love the water drops.', '2006-04-28 09:46:02.000000', NULL, 1),
