INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2353306, 326515, 45790, '<td valign="top">The dead/shriveling petals distract from the picture. I also don''t know what two complementary colors are being used here.</td>', 'The dead/shriveling petals distract from the picture. I also don''t know what two complementary colors are being used here.', '2006-04-28 13:05:21.000000', NULL, 1),
(2353314, 325240, 50674, '<td valign="top">excellent shot, fabulous colours - very nice composition indeed</td>', 'excellent shot, fabulous colours - very nice composition indeed', '2006-04-28 13:06:47.000000', NULL, 1),
(2353320, 323604, 45790, '<td valign="top">The halos  surrounding the foliage against the blue background are distracting and gives the picture an unnatural look. Perhaps a different angle to get the purple and yellow flowers a greater percentage of the frame, reducing the blue background?</td>', 'The halos  surrounding the foliage against the blue background are distracting and gives the picture an unnatural look. Perhaps a different angle to get the purple and yellow flowers a greater percentage of the frame, reducing the blue background?', '2006-04-28 13:08:01.000000', NULL, 1),
(2353321, 325974, 50674, '<td valign="top">I think you went a little over-board with the red there, too much of a contrast behind the apple, not a bad shot though</td>', 'I think you went a little over-board with the red there, too much of a contrast behind the apple, not a bad shot though', '2006-04-28 13:08:11.000000', NULL, 1),
(2353325, 325240, 45790, '<td valign="top">The upper third of the frame, being overexposed and out of focus, add nothing to this. The bottom half of the frame is beautiful, however, and extremely sharp!</td>', 'The upper third of the frame, being overexposed and out of focus, add nothing to this. The bottom half of the frame is beautiful, however, and extremely sharp!', '2006-04-28 13:09:45.000000', NULL, 1),
(2353329, 326438, 45790, '<td valign="top">Humorous meeting of challenge description!</td>', 'Humorous meeting of challenge description!', '2006-04-28 13:10:48.000000', NULL, 1),
(2353333, 326566, 50674, '<td valign="top">a nice break from all those beautiful but oh so "ordinary" flowers, thank you<br/>apart from that ... I like this photograph, the colours and excellent composition (not a bad title either)</td>', 'a nice break from all those beautiful but oh so "ordinary" flowers, thank youapart from that ... I like this photograph, the colours and excellent composition (not a bad title either)', '2006-04-28 13:12:41.000000', NULL, 1),
(2353337, 324280, 45790, '<td valign="top">Beautiful shot of purple flower in foreground with great lighting, exposure, and focus, but I think you could have found a better angle to get complementary yellow flowers involved, even out of focus, and less of the distracting leaves and grass at the bottom.</td>', 'Beautiful shot of purple flower in foreground with great lighting, exposure, and focus, but I think you could have found a better angle to get complementary yellow flowers involved, even out of focus, and less of the distracting leaves and grass at the bottom.', '2006-04-28 13:13:53.000000', NULL, 1),
(2353341, 326218, 45790, '<td valign="top">Nice capture. Cloudless sky adds to meeting the challenge description. I also like the framing and angle which gives good use of diagonals.</td>', 'Nice capture. Cloudless sky adds to meeting the challenge description. I also like the framing and angle which gives good use of diagonals.', '2006-04-28 13:15:34.000000', NULL, 1),
(2353346, 326048, 45790, '<td valign="top">I like this. It might be better cropping oout the upper 1/3 and right 1/3 of the frame to better feature the strong, natural complementary colors.</td>', 'I like this. It might be better cropping oout the upper 1/3 and right 1/3 of the frame to better feature the strong, natural complementary colors.', '2006-04-28 13:17:47.000000', NULL, 1),
