INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2362338, 326495, 55838, '<td valign="top">The best...blue ribbon in my opinion.  Perfect crop on the pepper and beautiful color.  The chameleon is even waving!</td>', 'The best...blue ribbon in my opinion.  Perfect crop on the pepper and beautiful color.  The chameleon is even waving!', '2006-04-30 12:54:08.000000', NULL, 1),
(2362341, 324592, 55838, '<td valign="top">I love the color and lighting on this.  I wouldn''t change a thing.</td>', 'I love the color and lighting on this.  I wouldn''t change a thing.', '2006-04-30 12:55:10.000000', NULL, 1),
(2362344, 323773, 55838, '<td valign="top">This is an interesting photo.  I love all the green with a little bit of lady.  Great idea.</td>', 'This is an interesting photo.  I love all the green with a little bit of lady.  Great idea.', '2006-04-30 12:56:10.000000', NULL, 1),
(2362348, 323929, 55838, '<td valign="top">This is beautiful.  Great colors and flow.  I have no idea what the orange is but it looks cool.  The light transitioning to dark to attractive too.</td>', 'This is beautiful.  Great colors and flow.  I have no idea what the orange is but it looks cool.  The light transitioning to dark to attractive too.', '2006-04-30 12:57:30.000000', NULL, 1),
(2362354, 326198, 55838, '<td valign="top">Very nice...dazling orange and the shapes in the blue smoke are attractive.  Nice mix of lightness and darkness.</td>', 'Very nice...dazling orange and the shapes in the blue smoke are attractive.  Nice mix of lightness and darkness.', '2006-04-30 13:00:09.000000', NULL, 1),
(2362359, 326475, 55838, '<td valign="top">Looks a little strange at first but I love that this is not the same old fruit shot!  It''s fun and the texture in the background makes it a much better shot than it would have been on a straight orange back.</td>', 'Looks a little strange at first but I love that this is not the same old fruit shot!  It''s fun and the texture in the background makes it a much better shot than it would have been on a straight orange back.', '2006-04-30 13:01:40.000000', NULL, 1),
(2362362, 326498, 55838, '<td valign="top">I like this.  Simple and lovely.  Golf balls were a godd choice...little dimples make the lighting more interesting.</td>', 'I like this.  Simple and lovely.  Golf balls were a godd choice...little dimples make the lighting more interesting.', '2006-04-30 13:02:33.000000', NULL, 1),
(2362363, 324586, 10818, '<td valign="top">That is really well done, awesome shot.</td>', 'That is really well done, awesome shot.', '2006-04-30 13:02:34.000000', NULL, 1),
(2362367, 326178, 10818, '<td valign="top">This is one of my favorites of the flower shots.</td>', 'This is one of my favorites of the flower shots.', '2006-04-30 13:04:28.000000', NULL, 1),
(2362368, 325396, 55838, '<td valign="top">Nice take on the colors.  I like that the set in the back alternate.  I also think you made a good decision on the placement of the focus.</td>', 'Nice take on the colors.  I like that the set in the back alternate.  I also think you made a good decision on the placement of the focus.', '2006-04-30 13:04:40.000000', NULL, 1),
(2362374, 326515, 55838, '<td valign="top">Never have weeds looked so lovely!  I like the composition and color and that the stems are at a bit of an angle.</td>', 'Never have weeds looked so lovely!  I like the composition and color and that the stems are at a bit of an angle.', '2006-04-30 13:06:03.000000', NULL, 1),
(2362377, 326396, 55838, '<td valign="top">Yay...something different!  Clean and bright.  Good choice on the lay of the tie.</td>', 'Yay...something different!  Clean and bright.  Good choice on the lay of the tie.', '2006-04-30 13:07:01.000000', NULL, 1),
(2362381, 326571, 45318, '<td valign="top">Nice idea..seems a little soft..</td>', 'Nice idea..seems a little soft..', '2006-04-30 13:08:10.000000', NULL, 1),
(2362392, 324957, 55838, '<td valign="top">My husband would whole-heartedly agree!  Good idea.  I might have cropped out a tad more of the white space at the bottom and top of the shot but the way you have it definitely works.</td>', 'My husband would whole-heartedly agree!  Good idea.  I might have cropped out a tad more of the white space at the bottom and top of the shot but the way you have it definitely works.', '2006-04-30 13:11:31.000000', NULL, 1),
(2362395, 325880, 55838, '<td valign="top">Crisp and clean colors.  The refelections work well too.  Nicely done.</td>', 'Crisp and clean colors.  The refelections work well too.  Nicely done.', '2006-04-30 13:12:09.000000', NULL, 1),
(2362413, 326423, 49716, '<td valign="top">Nice detail and focus.</td>', 'Nice detail and focus.', '2006-04-30 13:20:27.000000', NULL, 1),
(2362417, 326593, 49716, '<td valign="top">Great colours and sharpness.  I would probably have scored it even higher if it was either the glass and lemon or the roses.  Both together feels a bit ''confused''.</td>', 'Great colours and sharpness.  I would probably have scored it even higher if it was either the glass and lemon or the roses.  Both together feels a bit ''confused''.', '2006-04-30 13:21:59.000000', NULL, 1),
(2362426, 326570, 49716, '<td valign="top">Nice colours and sharpness, would a  bit more of the jug have made the composition stronger?</td>', 'Nice colours and sharpness, would a  bit more of the jug have made the composition stronger?', '2006-04-30 13:24:37.000000', NULL, 1),
(2362429, 326592, 49716, '<td valign="top">Great colours - and pin sharp too :-)</td>', 'Great colours - and pin sharp too :-)', '2006-04-30 13:25:07.000000', NULL, 1),
