INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2367524, 325366, 35602, '<td valign="top">Nice composition.  Needs to be sharper, though your colors work well together.</td>', 'Nice composition.  Needs to be sharper, though your colors work well together.', '2006-05-01 08:07:11.000000', NULL, 1),
(2367525, 326150, 35602, '<td valign="top">Needs better focus.</td>', 'Needs better focus.', '2006-05-01 08:07:26.000000', NULL, 1),
(2367532, 324898, 35602, '<td valign="top">Very creative concept.  Very out of focus, though, and I find the dropped paint may have been better if you used less on the white background.</td>', 'Very creative concept.  Very out of focus, though, and I find the dropped paint may have been better if you used less on the white background.', '2006-05-01 08:09:45.000000', NULL, 1),
(2367537, 325198, 35602, '<td valign="top">Very clear shot, though a bit dull in saturation.  Maybe a bit more contrast.</td>', 'Very clear shot, though a bit dull in saturation.  Maybe a bit more contrast.', '2006-05-01 08:10:27.000000', NULL, 1),
(2367540, 326438, 35602, '<td valign="top">Seems very overexposed.</td>', 'Seems very overexposed.', '2006-05-01 08:11:29.000000', NULL, 1),
(2367543, 326325, 35602, '<td valign="top">Wonderful play of light and dark on the petals.  you really get the sense of texture of the petals on this one.  Very "touchable" photo.</td>', 'Wonderful play of light and dark on the petals.  you really get the sense of texture of the petals on this one.  Very "touchable" photo.', '2006-05-01 08:12:25.000000', NULL, 1),
(2367547, 325970, 35602, '<td valign="top">Not enough interest to the photo.</td>', 'Not enough interest to the photo.', '2006-05-01 08:13:56.000000', NULL, 1),
(2367555, 323610, 35602, '<td valign="top">Need to reduce your grain.  If you haven''t got a noise reducing program there are a few that are free on the internet.  I downloaded neat image which works okay, but others have programs they have purchased.  Ask the question in the boards about it and you will get plenty of help on programs that are available.</td>', 'Need to reduce your grain.  If you haven''t got a noise reducing program there are a few that are free on the internet.  I downloaded neat image which works okay, but others have programs they have purchased.  Ask the question in the boards about it and you will get plenty of help on programs that are available.', '2006-05-01 08:15:26.000000', NULL, 1),
(2367560, 324625, 35602, '<td valign="top">Looks like there is more than meets the eye here.  Ha, ha.</td>', 'Looks like there is more than meets the eye here.  Ha, ha.', '2006-05-01 08:17:04.000000', NULL, 1),
(2367564, 325868, 35602, '<td valign="top">Very nice portrait.  Nice job on showing the silky feel of the fabric with your lighting choice.</td>', 'Very nice portrait.  Nice job on showing the silky feel of the fabric with your lighting choice.', '2006-05-01 08:18:08.000000', NULL, 1),
(2367568, 325483, 35602, '<td valign="top">Composition needs work.  Didn''t care for the straight line dividing the colors.  Also focus was way too soft.</td>', 'Composition needs work.  Didn''t care for the straight line dividing the colors.  Also focus was way too soft.', '2006-05-01 08:19:57.000000', NULL, 1),
(2367571, 325980, 35602, '<td valign="top">Beautiful leaf detail.  The play of light is magnificent.  Also liked the black background.  Very nice detail.</td>', 'Beautiful leaf detail.  The play of light is magnificent.  Also liked the black background.  Very nice detail.', '2006-05-01 08:22:03.000000', NULL, 1),
(2367572, 326497, 35602, '<td valign="top">Must be spring.  I wonder which is the boy and which is the girl.</td>', 'Must be spring.  I wonder which is the boy and which is the girl.', '2006-05-01 08:22:53.000000', NULL, 1),
(2367579, 325910, 35602, '<td valign="top">Highlights are way overblown.  IF you can attach a neutral density filter to your camera, much of the problem with imbalance of light would be taken care of.</td>', 'Highlights are way overblown.  IF you can attach a neutral density filter to your camera, much of the problem with imbalance of light would be taken care of.', '2006-05-01 08:24:52.000000', NULL, 1),
