INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2374067, 325101, 58305, '<td valign="top">Funny- I like that it looks like a tongue, but isn''t too obvious!<br/>Keep up the good work!</td>', 'Funny- I like that it looks like a tongue, but isn''t too obvious!Keep up the good work!', '2006-05-02 22:31:54.000000', NULL, 1),
(2374068, 326146, 43565, '<td valign="top">Interesting textures, but I don''t see complementary colors.</td>', 'Interesting textures, but I don''t see complementary colors.', '2006-05-02 22:32:03.000000', NULL, 1),
